    "author": "William Edmund Hick",
    "channelName": "Laws of UX Design",
    "sandboxType": "hicks",
    "caseStudies": [
      {
        "company": "Netflix",
        "logo": "tv",
        "title": "'Top 10 Today' & 'Play Something'",
        "description": "Netflix combats decision fatigue from a catalog of 10,000+ titles by offering curated Top 10 lists and a single 'Play Something' button that auto-selects tailored content."
      },
      {
        "company": "Apple TV",
        "logo": "remote",
        "title": "Minimalist Siri Remote",
        "description": "Apple replaced traditional TV remotes (40+ confusing buttons) with a sleek pad having just 6 essential buttons, drastically reducing user decision time."
      },
      {
        "company": "Google",
        "logo": "search",
        "title": "Clean Search Homepage",
        "description": "Google's homepage presents a single input box and two buttons ('Google Search' and 'I'm Feeling Lucky') eliminating all distraction."
      }
    ],
    "keyTakeaways": [
      "Minimize choices when response times are critical (e.g. checkout flows, onboarding).",
      "Break complex processes into step-by-step progressive wizards.",
      "Use default selections or 'Recommended' badges to guide user decision-making."
    ],
