    "id": "paradox-of-the-active-user",
    "title": "Paradox of the Active User",
    "subtitle": "Users Skip Documentation & Jump Right In",
    "category": "Heuristic",
    "rating": 4.5,
    "impactLevel": "Medium",
    "badge": "New",
    "summary": "Users never read manuals but start using the software immediately.",
    "description": "The Paradox of the Active User states that users never read manuals or documentation before starting to use software. Instead, they want to start immediately to accomplish their immediate goals, even if reading guidance would save them significant time in the long run.",
    "videoUrl": "",
    "youtubeEmbedUrl": "https://www.youtube.com/embed/xxHFnL5rG3s",
    "officialUrl": "https://lawsofux.com/paradox-of-the-active-user/",
