    "subtitle": "Primacy & Recency Recall Bias",
    "category": "Cognitive",
    "rating": 4.9,
    "impactLevel": "Critical",
    "badge": "Cognitive Core",
    "summary": "Users have a propensity to best remember the first and last items in a series.",
    "description": "Coined by Hermann Ebbinghaus, this principle combines the Primacy Effect (first items are stored in long-term memory) and the Recency Effect (last items are fresh in short-term working memory). Items placed in the middle of a list are forgotten most easily.",
    "videoUrl": "https://media.w3.org/2010/05/bunny/trailer.mp4",
    "youtubeEmbedUrl": "https://www.youtube.com/embed/0OMgbicYYE4",
    "officialUrl": "https://lawsofux.com/serial-position-effect/",
    "duration": "12m 10s",
    "year": "1885",
    "author": "Hermann Ebbinghaus",
    "channelName": "Alexis Solomon",
    "sandboxType": "serialPosition",
    "caseStudies": [
      {
        "company": "Instagram & Spotify",
        "logo": "bar-chart-2",
        "title": "Bottom Navigation Edge Placement",
        "description": "Apps place the two most critical features—Home on the far-left (first) and Profile/Library on the far-right (last)—leveraging the serial position edge recall bias."
      },
      {
        "company": "Apple",
        "logo": "list",
        "title": "Keynote Feature Summaries",
        "description": "Apple keynotes list the most revolutionary feature first (one more thing) and recap key specs at the very end of the presentation."
      }
    ],
    "keyTakeaways": [
      "Place vital navigation actions at the beginning and end of toolbars or menus.",
      "Key benefits in promotional bullet lists should be listed first and last.",
      "Limit middle list clutter to reduce memory retrieval drops."
    ],
